package android.content; import android.app.*; import android.os.*; import java.util.*; public class Context { public static final String POWER_SERVICE="power",NOTIFICATION_SERVICE="notification"; public static boolean rejectStart; public static int permission; public static final List<Intent> starts=new ArrayList<>(); public Object getSystemService(String s){return POWER_SERVICE.equals(s)?new PowerManager():NotificationManager.INSTANCE;} public String getPackageName(){return "telegram.test";} public Object startForegroundService(Intent i){return startService(i);} public Object startService(Intent i){if(rejectStart)throw new IllegalStateException("secret background restriction");starts.add(i);return null;} public int checkSelfPermission(String p){return permission;} }